const int ENA = 25, IN1 = 26, IN2 = 27;     // left motor
const int ENB = 13, IN3 = 32, IN4 = 33;     // right motor

// speed from -255 (full reverse) to 255 (full forward)
void motor(int en, int a, int b, int speed) {
  digitalWrite(a, speed > 0);
  digitalWrite(b, speed < 0);
  ledcWrite(en, abs(speed));                // PWM on the enable pin
}

void drive(int left, int right) {
  motor(ENA, IN1, IN2, left);
  motor(ENB, IN3, IN4, right);
}

void setup() {
  pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT);
  ledcAttach(ENA, 1000, 8);                 // 1 kHz PWM, values 0 to 255
  ledcAttach(ENB, 1000, 8);                 // (Arduino-ESP32 core 3.x)
}

void loop() {
  drive(180, 180); delay(1000);             // forward
  drive(0, 0);     delay(1000);             // stop
}

const int TRIG = 18, ECHO = 19;

void setup() {
  Serial.begin(115200);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
}

float distanceCm() {
  digitalWrite(TRIG, LOW);  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);   // a 10 us pulse starts a ping
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);              // wait up to 30 ms for the echo
  if (us == 0) return 999;                           // nothing came back
  return us * 0.0343 / 2;                            // there and back, so halve it
}

void loop() {
  Serial.println(distanceCm());
  delay(200);
}

#include <ESP32Servo.h>
Servo neck;                           // the servo that turns the sensor

float lookAt(int angle) {
  neck.write(angle);
  delay(400);                         // let the servo arrive
  return distanceCm();
}

void loop() {
  if (distanceCm() > 25) {            // clear ahead: keep going
    drive(180, 180);
    delay(50);
    return;
  }
  drive(0, 0);  delay(200);           // too close: stop
  drive(-150, -150);  delay(400);     // back up a little
  drive(0, 0);
  float left = lookAt(150), right = lookAt(30);   // swap if yours are reversed
  neck.write(90);                     // face forward again
  if (left > right) drive(-160, 160); else drive(160, -160);
  delay(450);                         // about a quarter turn: tune this
  drive(0, 0);
}
